# ── helpers local to this wizard ──────────────────────────────────────────
AGREGADO_DIR="${AGREGADO_DIR:-$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)}"
HOMELAB_APPS_DIR="${HOMELAB_APPS_DIR:-$AGREGADO_DIR/../homelab-apps}"
CUTOVER_LOG="${CUTOVER_LOG:-$AGREGADO_DIR/backups/cutover-$(date -u +%Y%m%dT%H%M%SZ).log}"
cd "$AGREGADO_DIR"
mkdir -p "$(dirname "$CUTOVER_LOG")"

# log "text" appends a timestamped line to the cutover log.
log() { printf '%s %s\n' "$(date -u +%FT%TZ)" "$*" >> "$CUTOVER_LOG"; }

# run CMD... shows and logs the command, streams its output into the log, and
# lets the human decide what to do on failure instead of aborting the wizard.
run() {
  say "\$ $*"; log "RUN $*"
  local rc=0
  "$@" 2>&1 | tee -a "$CUTOVER_LOG" || rc=${PIPESTATUS[0]}
  if (( rc != 0 )); then
    warn "exit status $rc"; log "FAIL($rc) $*"
    confirm "That failed. Continue anyway? (n aborts the wizard)" || { say "Stopped. Log: $CUTOVER_LOG"; exit 1; }
  fi
}

# gate "text" requires an explicit yes, or stops the wizard.
gate() { confirm "$1" || { log "ABORT at: $1"; say "Stopped. Re-run later; log: $CUTOVER_LOG"; exit 1; }; log "OK $1"; }

run_wizard() {

TOTAL_STAGES=15

banner "Agregado production cutover (#84)"
say "Log: $CUTOVER_LOG"
say "Runbook: docs/runbooks/production-cutover.md"
say "One-way stages are marked [one-way] and ask for an explicit yes."
log "START commit=$(git rev-parse HEAD 2>/dev/null || echo unknown)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Go / no-go"
say "Every line must be true. Anything 'n' stops the wizard."
gate "#78, #79, #80, #81, #82, #83 are closed?"
gate "Map #110 done and n8n/workflows/newsletter-ingest.json exported?"
gate "A ~2h window is free and 08:00 Berlin is not inside it?"
gate "You know where off-box backup copies go?"
say "Running both test suites on the deploy commit…"
run go test ./...
run bash -c 'cd n8n && npm test'

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Final Karakeep backup (AC 1)"
say "Forces one run of the verified backup sidecar in $HOMELAB_APPS_DIR."
gate "Run the Karakeep backup now?"
run bash -c "cd '$HOMELAB_APPS_DIR' && docker compose run --rm -e BACKUP_ONCE=1 karakeep-backup"
say "The run must report verified assets and an upload. Read the output above."
gate "Backup succeeded and uploaded?"
note "Optional but recommended: confirm the archive in R2 and rehearse a restore (homelab-apps/docs/karakeep-backup.md)."
pause "Press Enter when done"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "OPML export of current Sources"
ask OLD_AGREGADO_URL "Old Agregado base URL (e.g. http://localhost:8080):"
mkdir -p backups
OPML="backups/sources-$(date -u +%F).opml"
run curl -fsS "$OLD_AGREGADO_URL/api/sources/export" -o "$OPML"
[[ -s "$OPML" ]] || { warn "OPML is empty or missing"; exit 1; }
say "Saved $OPML ($(wc -c < "$OPML") bytes, $(grep -c '<outline' "$OPML" || true) outlines)"
log "OPML $OPML sha256=$(sha256sum "$OPML" | cut -d' ' -f1)"
pause "Copy it off-box now, then press Enter"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Migration prerequisites"
ask KARAKEEP_DOMAIN "Your base domain (e.g. example.com):"
open_url "https://karakeep.$KARAKEEP_DOMAIN/settings/api-keys"
step "In Karakeep: Settings → API Keys → create one named 'agregado-migration'."
ask KARAKEEP_ADDRESS "Karakeep origin, no /api/v1 (e.g. https://karakeep.$KARAKEEP_DOMAIN):"
ask_secret KARAKEEP_API_KEY "Paste the API key:"
write_env KARAKEEP_ADDRESS "$KARAKEEP_ADDRESS"
write_env KARAKEEP_API_KEY "$KARAKEEP_API_KEY"
ask POSTGRESQL_URL "POSTGRESQL_URL for the old database:"
write_env POSTGRESQL_URL "$POSTGRESQL_URL"
run migrate -database "$POSTGRESQL_URL" -path migrations up

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Migration dry run"
set -a; source "$ENV_FILE"; set +a
run make migrate-ownership
say "Check: FAIL is 0; source_config and article_bodies show DEST 0;"
say "SKIP is roughly your newsletter volume; samples read DIFF 'absent' (nothing written)."
gate "Dry run looks right?"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Apply the migration [one-way into Karakeep / Article Index] (AC 2)"
warn "Writes Bookmarks into Karakeep and rows into the Article Index."
gate "Apply now?"
run make migrate-ownership-apply
say "Samples should be OK (except legitimately preserved live rows). FAIL must be 0."
gate "First apply is clean?"
say "Second apply is the idempotency check: every class DEST 0."
run make migrate-ownership-apply
gate "Second apply shows DEST 0 everywhere and totals reconcile (SOURCE = DEST + SKIP + DUP)?"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Final cold dump [briefly stops the agregado container] (AC 1)"
warn "The script stops agregado for the dump and restarts it on exit."
gate "Take the cold dump now?"
run scripts/legacy-postgres-dump.sh ./backups
MANIFEST=$(ls -t backups/agregado-legacy-*.manifest.txt | head -1)
grep -qE '^restore: +VERIFIED' "$MANIFEST" || { warn "$MANIFEST does not say restore: VERIFIED"; exit 1; }
say "Manifest $MANIFEST says restore: VERIFIED."
log "DUMP manifest=$MANIFEST"
run sha256sum -c <<< "$(grep sha256 "$MANIFEST" | awk '{print $2}')  ${MANIFEST/.manifest.txt/.dump}"
pause "Copy the .dump and manifest OFF-BOX now (keep forever), then press Enter"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Deploy with the legacy RSS poller off"
say "Miniflux takes over the feeds next. The in-process poller must be off first,"
say "or every Article is ingested and enriched (and paid for) twice."
set_var RSS_POLLER_ENABLED false
step "Deploy main with this variable: push/merge to main, or re-run the latest"
step "'Deploy to local server' run (gh run rerun <id>); reruns read current vars."
pause "Press Enter when the deploy run is green"
run bash -c "docker compose --profile prod logs agregado 2>&1 | grep -m1 'legacy RSS poller disabled'"
ask AGREGADO_BASE_URL "New Agregado base URL (tailnet):"
write_env AGREGADO_BASE_URL "$AGREGADO_BASE_URL"
ask_secret ENRICHMENT_SECRET "ENRICHMENT_SECRET (same value as the deploy secret):"
write_env ENRICHMENT_SECRET "$ENRICHMENT_SECRET"
run curl -fsS "$AGREGADO_BASE_URL/health"
run curl -fsS "$AGREGADO_BASE_URL/health/db"
gate "Log line 'legacy RSS poller disabled' present and both health checks 200?"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "n8n: import workflows"
open_url "https://n8n.$KARAKEEP_DOMAIN"
say "Import from n8n/workflows/: article-enrichment, newsletter-ingest, daily-digest, preferences-sync."
note "CLI: n8n import:workflow --input=<file> (inside the n8n container), or paste into the editor."
say "Set env + credentials per n8n/README.md → 'Configuration (n8n)':"
step "Resend, Cloudflare D1/R2, RESEND_WEBHOOK_SECRET, BRIDGE_PERMALINK_SECRET (never rotate)"
step "MINIFLUX_WEBHOOK_SECRET, BRIDGE_ORIGIN, AGREGADO_BASE_URL, ENRICHMENT_SECRET"
step "SMTP credential, DIGEST_RECIPIENT_EMAIL, DIGEST_FROM_EMAIL"
step "Google Drive OAuth2 (full scope, app 'In production'), PREFERENCES_DOC_ID"
say "Enrichment refuses to run until a preference profile is stored (ADR-0010)."
code=$(curl -s -o /dev/null -w '%{http_code}' -H "X-Enrichment-Secret: $ENRICHMENT_SECRET" "$AGREGADO_BASE_URL/api/private/preferences")
say "GET /api/private/preferences → $code"
if [[ "$code" != "200" ]]; then
  step "No profile yet: in n8n, run preferences-sync once by hand (Execute workflow)."
  pause "Press Enter when it succeeded"
  run curl -fsS -o /dev/null -H "X-Enrichment-Secret: $ENRICHMENT_SECRET" "$AGREGADO_BASE_URL/api/private/preferences"
fi
warn "Activate ONLY the webhook workflows now. Leave daily-digest and preferences-sync schedules OFF."
pause "Press Enter when imported and the webhook workflows are active"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Miniflux: subscriptions and webhook"
open_url "https://miniflux.$KARAKEEP_DOMAIN/import"
step "Import $OPML (Settings → Import)."
open_url "https://miniflux.$KARAKEEP_DOMAIN/integrations"
step "Integrations → Webhook: URL = the n8n article-enrichment webhook (with its random suffix)."
step "Set the webhook secret to your MINIFLUX_WEBHOOK_SECRET."
step "Check entry retention isn't pruning Articles you want."
warn "The first fetch of every feed sends its current entries to enrichment: expect a model-cost burst."
pause "Press Enter when Miniflux is configured"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Newsletter ingestion and public routes"
say "Follow docs/runbooks/newsletter-source-onboarding.md for each Source:"
step "D1 source row → status 'active' → subscribe in Miniflux to the Bridge feed."
step "Enable the Cloudflare Tunnel rule for the Resend webhook path."
warn "Confirm how /r/ and /f/ links are reachable from your phone (ADR-0001 / ADR-0008)."
pause "Press Enter when done"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Verify live ingestion (AC 3)"
step "RSS: force a refresh of a fast feed in Miniflux. Confirm the entry, a successful article-enrichment execution, and an article_index row with Score/tags/summary."
step "Newsletter with no canonical URL: confirm Bridge → Miniflux → enrichment → article_index keyed by the permalink UUID."
gate "A live RSS Article reached enrichment and the Digest queue?"
gate "A newsletter with no canonical URL reached enrichment?"

# ── 13 ────────────────────────────────────────────────────────────────────
stage "Verify Open and feedback (AC 4)"
ask LINK_BASE "Base URL the Digest links use (as seen from your phone):"
ask ARTICLE_ID "An Article Index id/key from article_index:"
say "Open (twice; expect a redirect both times):"
run curl -sI -o /dev/null -w '%{http_code} -> %{redirect_url}\n' "$LINK_BASE/r/$ARTICLE_ID"
run curl -sI -o /dev/null -w '%{http_code} -> %{redirect_url}\n' "$LINK_BASE/r/$ARTICLE_ID"
note "In the DB: exactly ONE Open for this Article."
gate "Exactly one Open recorded?"
say "Feedback (up then down replaces; bad vote is 404):"
run curl -fsS "$LINK_BASE/f/$ARTICLE_ID/up"
run curl -fsS "$LINK_BASE/f/$ARTICLE_ID/down"
run curl -s -o /dev/null -w '%{http_code}\n' "$LINK_BASE/f/$ARTICLE_ID/sideways"
gate "One current vote row, now 'down', first_voted_at unchanged, sideways was 404?"

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Digest retry and preferences proposal (AC 5-6)"
D=$(date -u +%F)
say "Fetching the persisted Digest for $D twice; bodies must be identical."
A=$(curl -fsS -X POST -H "X-Enrichment-Secret: $ENRICHMENT_SECRET" "$AGREGADO_BASE_URL/api/private/digests/$D" | sha256sum | cut -d' ' -f1)
B=$(curl -fsS -X POST -H "X-Enrichment-Secret: $ENRICHMENT_SECRET" "$AGREGADO_BASE_URL/api/private/digests/$D" | sha256sum | cut -d' ' -f1)
log "DIGEST $D sha256 A=$A B=$B"
[[ "$A" == "$B" ]] || { warn "Digest bodies differ between calls: it was regenerated"; exit 1; }
say "Identical ($A)."
step "In n8n, run daily-digest manually; confirm the email arrives."
open_url "https://${LANGFUSE_HOST:-langfuse.$KARAKEEP_DOMAIN}"
step "Langfuse: no new digest_select trace for $D after the second fetch."
gate "No extra model call for the retry?"
step "In n8n, run preferences-sync manually."
warn "AC 6 asks for a reviewable proposal; ADR-0010 removed that gate: the workflow writes the Doc directly."
gate "Accept the alert diff + Doc revision history as the review? (n: stop and open a follow-up issue)"
step "Edit the Doc into a malformed state, run again, expect a 400 alert, then revert."
pause "Press Enter when done"
step "Now ACTIVATE the Schedule triggers on daily-digest and preferences-sync."
pause "Press Enter when both are active"

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Stop the old stack and verify rollback (AC 7)"
warn "Stop, do NOT remove containers/images/volumes. Do NOT drop old tables (#85)."
say "The old stack's only background loop was the RSS poller (off since stage 8);"
say "the legacy Digest only ever ran via POST /api/digest/send. RabbitMQ and the"
say "consumers stay up until #85 removes them: they are idle without the poller."
say "Legacy newsletter ingress: any hit on /webhook/email means a publisher still"
say "mails an old address. Re-onboard it (newsletter-source-onboarding.md)."
run bash -c "docker compose --profile prod logs --since 24h agregado 2>&1 | grep -c '/webhook/email' || true"
gate "Poller off, no unexplained /webhook/email traffic?"
say "Rollback, if a trigger in docs/runbooks/production-cutover.md fires:"
step "Deactivate the four n8n workflows; disable the Miniflux webhook."
step "gh variable set RSS_POLLER_ENABLED --body true, then re-run the deploy."
step "The old tables are untouched; the dump below is the fallback if they are not."
say "Rollback drill from the OFF-BOX copy of the dump:"
step "createdb agregado_restored && pg_restore -d agregado_restored --no-owner --no-acl <dump>"
step "Compare row counts to $MANIFEST."
step "Boot the retained old-stack image against it; /health/db must be 200."
step "Confirm the PREFERENCES Doc has a revision to roll back to."
gate "Restore, boot and Doc revision all verified?"
log "DONE cutover wizard"

say "Cutover log: $CUTOVER_LOG"
say "Next: comment the log summary on #84, close it, unblock #85 after the observation window (~48h)."

finish
}

run_wizard "$@"; exit
